(608996, 63064, 14614, '<td valign="top">wow on the sky! siloette works to add to the mood.  My pick for a ribbon.</td>', 'wow on the sky! siloette works to add to the mood.  My pick for a ribbon.', '2004-03-04 09:19:28.000000', NULL, 1),
(608997, 63126, 14614, '<td valign="top">interesting use of thirds - a wow shot, wish I was there. my pick for a ribbon</td>', 'interesting use of thirds - a wow shot, wish I was there. my pick for a ribbon', '2004-03-04 09:19:48.000000', NULL, 1),
