(609152, 63064, 14986, '<td valign="top">Lovely.  I like the hammock.</td>', 'Lovely.  I like the hammock.', '2004-03-04 10:39:05.000000', NULL, 1),
(609153, 62693, 16402, '<td valign="top">Image seems just a bit dark to me but that''s a minor thing as far as I''m concerned. Nice job.</td>', 'Image seems just a bit dark to me but that''s a minor thing as far as I''m concerned. Nice job.', '2004-03-04 10:39:44.000000', NULL, 1),
(609154, 62386, 16095, '<td valign="top">the geometrical shapes in the shot are so intriguing, yet the trashcan does a good job breaking up the monotny. like the color and focal point.</td>', 'the geometrical shapes in the shot are so intriguing, yet the trashcan does a good job breaking up the monotny. like the color and focal point.', '2004-03-04 10:40:07.000000', NULL, 1),
