(611044, 62976, 245, '<td valign="top">this picture is fantastic. but not silent.</td>', 'this picture is fantastic. but not silent.', '2004-03-05 17:19:18.000000', NULL, 1),
(611046, 62599, 16095, '<td valign="top">this is a different twist on the hand over mouth shot, i like it. It is technically fine work but has a alot of lines and angles that disrupt flow of image.</td>', 'this is a different twist on the hand over mouth shot, i like it. It is technically fine work but has a alot of lines and angles that disrupt flow of image.', '2004-03-05 17:20:03.000000', NULL, 1),
(611047, 63105, 16095, '<td valign="top">this is such a great shot, the composition really works, but it seems like bone crushing (or mannequin crushing) would be quite loud.</td>', 'this is such a great shot, the composition really works, but it seems like bone crushing (or mannequin crushing) would be quite loud.', '2004-03-05 17:21:47.000000', NULL, 1),
(611048, 62588, 16095, '<td valign="top">this is technically sound and i enjoy the color and composition but unsure wether this would be recognizable without the title.</td>', 'this is technically sound and i enjoy the color and composition but unsure wether this would be recognizable without the title.', '2004-03-05 17:22:49.000000', NULL, 1),
(611049, 62961, 16982, '<td valign="top">Superb colours.  Very good contrast and sharpness.  If the house in the lower middle area was not visible, perfect!</td>', 'Superb colours.  Very good contrast and sharpness.  If the house in the lower middle area was not visible, perfect!', '2004-03-05 17:23:05.000000', NULL, 1),
(611050, 62830, 245, '<td valign="top">i can''t get away from the electric buzz of those lamps</td>', 'i can''t get away from the electric buzz of those lamps', '2004-03-05 17:23:35.000000', NULL, 1),
(611051, 62437, 16982, '<td valign="top">This is very good; interesting angle.  Black keys are a bit dusty!</td>', 'This is very good; interesting angle.  Black keys are a bit dusty!', '2004-03-05 17:23:50.000000', NULL, 1),
(611052, 62488, 16095, '<td valign="top">this is nice and it conveys a calm peaceful feeling, I would''ve liked to see it cropped at the tree line to give the beautifully smooth water a little more drama.</td>', 'this is nice and it conveys a calm peaceful feeling, I would''ve liked to see it cropped at the tree line to give the beautifully smooth water a little more drama.', '2004-03-05 17:24:13.000000', NULL, 1),
(611055, 62970, 16982, '<td valign="top">Wow, it feels like we''re looking at this scene from a hundred miles away!  This is what all panoramas should be like.</td>', 'Wow, it feels like we''re looking at this scene from a hundred miles away!  This is what all panoramas should be like.', '2004-03-05 17:25:56.000000', NULL, 1),
