(611529, 62734, 5792, '<td valign="top">The waterfall on the lower left is a little washed out, but this is an excellent B&amp;W</td>', 'The waterfall on the lower left is a little washed out, but this is an excellent B&W', '2004-03-06 00:15:48.000000', NULL, 1),
(611531, 62516, 5792, '<td valign="top">Great tone and composition</td>', 'Great tone and composition', '2004-03-06 00:19:10.000000', NULL, 1),
(611532, 62991, 5792, '<td valign="top">Nice B&amp;W. Well composed.</td>', 'Nice B&W. Well composed.', '2004-03-06 00:20:10.000000', NULL, 1),
(611534, 62360, 5792, '<td valign="top">You have a very unusual concept of silence. The image is well done and has decent tonal range.</td>', 'You have a very unusual concept of silence. The image is well done and has decent tonal range.', '2004-03-06 00:22:27.000000', NULL, 1),
(611536, 62477, 5792, '<td valign="top">Interesting composition. It almost has a rainbow effect with the book colors.</td>', 'Interesting composition. It almost has a rainbow effect with the book colors.', '2004-03-06 00:29:51.000000', NULL, 1),
(611553, 63115, 5792, '<td valign="top">Great clarity and very good yellow tones.</td>', 'Great clarity and very good yellow tones.', '2004-03-06 01:31:11.000000', NULL, 1),
(611554, 63081, 5792, '<td valign="top">Excellent colors and well  composed.</td>', 'Excellent colors and well  composed.', '2004-03-06 01:32:51.000000', NULL, 1),
