(614962, 63091, 11467, '<td valign="top">Image seems very soft. (Maybe intentional)</td>', 'Image seems very soft. (Maybe intentional)', '2004-03-09 07:39:41.000000', NULL, 1),
(614963, 62691, 11467, '<td valign="top">Not much to see. Too dark.</td>', 'Not much to see. Too dark.', '2004-03-09 07:42:13.000000', NULL, 1),
