(619818, 62488, 6150, '<td valign="top">What a beautiful photograph.  Congratulations!!</td>', 'What a beautiful photograph.  Congratulations!!', '2004-03-13 09:00:24.000000', NULL, 0),
(619819, 62361, 6150, '<td valign="top">Beautiful shot.  Congratulations on first place.</td>', 'Beautiful shot.  Congratulations on first place.', '2004-03-13 09:04:02.000000', NULL, 0),
